// requirement: REQ-1.1
import { test, expect, action, openHome } from './helpers';

test('REQ-1.1: Open the workspace', async ({ page }) => {
  await openHome(page);
  const sidebar = page.getByRole('navigation', { name: 'Sidebar', exact: true });
  await expect(sidebar).toBeVisible();
  await expect(action(page, 'Toggle sidebar')).toHaveAttribute('aria-expanded', 'true');
  for (const name of ['Notes', 'Archived']) {
    await expect(action(sidebar, name)).toBeVisible();
  }
  await expect(action(sidebar, 'Notes')).toHaveAttribute('aria-current', 'true');
});

// requirement: REQ-2.1
import { test, expect, note, section, openHome, createNote } from './helpers';
import { identity } from './fixtures/data';

test('REQ-2.1: Separate pinned and regular notes', async ({ page }, info) => {
  await openHome(page);
  const pinned = identity(info, 'Sprint goals');
  const regular = identity(info, 'Groceries');
  await createNote(page, pinned, 'Finish the sprint', { pinned: true });
  await createNote(page, regular, 'Milk and bread');
  await expect(section(page, 'Pinned notes')).toHaveCount(1);
  await expect(section(page, 'Other notes')).toHaveCount(1);
  await expect(section(page, 'Pinned notes').getByRole('region', { name: pinned, exact: true })).toHaveCount(1);
  await expect(section(page, 'Other notes').getByRole('region', { name: regular, exact: true })).toHaveCount(1);
  await expect(section(page, 'Other notes').getByRole('region', { name: pinned, exact: true })).toHaveCount(0);
  await expect(section(page, 'Pinned notes').getByRole('region', { name: regular, exact: true })).toHaveCount(0);
  await expect(note(page, pinned)).toHaveCount(1);
  await expect(note(page, regular)).toHaveCount(1);
});

// requirement: REQ-2.2
import { test, openHome, createNote, expectNote } from './helpers';
import { identity } from './fixtures/data';

test('REQ-2.2: Autosave on closing the editor', async ({ page }, info) => {
  await openHome(page);
  await createNote(page, identity(info, 'New note'), 'First line\nSecond line');
});

test('REQ-2.2: Keep a created note after reload', async ({ page }, info) => {
  await openHome(page);
  const title = identity(info, 'Persistent note');
  await createNote(page, title, 'Saved personal content');
  await page.reload();
  await expectNote(page, title, 'Saved personal content');
});

// requirement: REQ-2.3
import { test, expect, action, note, editor, openHome, createNote, expectNote } from './helpers';
import { identity } from './fixtures/data';

test('REQ-2.3: Save an edited note', async ({ page }, info) => {
  await openHome(page);
  const title = identity(info, 'Project ideas');
  await createNote(page, title, 'Initial editable content');
  await action(note(page, title), `Open ${title}`).click();
  await expect(editor(page).getByRole('textbox', { name: 'Title', exact: true })).toHaveValue(title);
  const content = editor(page).getByRole('textbox', { name: 'Content', exact: true });
  await expect(content).toHaveValue('Initial editable content');
  await content.fill('Updated editable content');
  await action(editor(page), 'Close').click();
  await expect(editor(page)).toBeHidden();
  await page.reload();
  await expectNote(page, title, 'Updated editable content');
  await expect(note(page, title).getByText('Initial editable content', { exact: true })).toHaveCount(0);
});

// requirement: REQ-2.4
import { test, expect, action, note, notice, section, openHome, navigate, createNote, archiveNote, expectNote } from './helpers';
import { identity } from './fixtures/data';

test('REQ-2.4: Archive a note into its separate list', async ({ page }, info) => {
  await openHome(page);
  const title = identity(info, 'Travel plans 2.5.1');
  const active = identity(info, 'Active archive control');
  await createNote(page, title, 'Trip itinerary');
  await createNote(page, active, 'Stay active');
  await archiveNote(page, title);
  await expect(action(notice(page, 'Note archived'), 'Undo')).toBeVisible();
  await navigate(page, 'Archived');
  await expect(section(page, 'Archived notes')).toBeVisible();
  await expectNote(page, title, 'Trip itinerary');
  await expect(note(page, active)).toBeHidden();
  await navigate(page, 'Notes');
  await page.reload();
  await expect(note(page, title)).toBeHidden();
  await expectNote(page, active, 'Stay active');
});

test('REQ-2.4: Undo archiving', async ({ page }, info) => {
  await openHome(page);
  const title = identity(info, 'Travel plans 2.5.2');
  await createNote(page, title, 'Return this itinerary');
  await archiveNote(page, title);
  await action(notice(page, 'Note archived'), 'Undo').click();
  await expect(notice(page, 'Action undone')).toBeVisible();
  await expectNote(page, title, 'Return this itinerary');
  await navigate(page, 'Archived');
  await expect(note(page, title)).toBeHidden();
});

test('REQ-2.4: Unarchive the selected note', async ({ page }, info) => {
  await openHome(page);
  const title = identity(info, 'Travel plans 2.5.4');
  const other = identity(info, 'Other archived note');
  await createNote(page, title, 'Selected itinerary');
  await createNote(page, other, 'Other itinerary');
  await archiveNote(page, title);
  await archiveNote(page, other);
  await navigate(page, 'Archived');
  await expectNote(page, title, 'Selected itinerary');
  await expectNote(page, other, 'Other itinerary');
  await note(page, title).hover();
  await action(note(page, title), `Unarchive ${title}`).click();
  await expect(note(page, title)).toBeHidden();
  await expectNote(page, other, 'Other itinerary');
  await navigate(page, 'Notes');
  await page.reload();
  await expectNote(page, title, 'Selected itinerary');
  await expect(note(page, other)).toBeHidden();
});

// requirement: REQ-2.5
import { test, expect, action, note, section, openHome, createNote, expectNote } from './helpers';
import { identity } from './fixtures/data';

test('REQ-2.5: Pin an existing note', async ({ page }, info) => {
  await openHome(page);
  const title = identity(info, 'Meeting agenda 2.8.1');
  await createNote(page, title, 'Discuss the launch');
  await note(page, title).hover();
  await action(note(page, title), `Pin ${title}`).click();
  await page.reload();
  await expectNote(page, title, 'Discuss the launch');
  await expect(section(page, 'Pinned notes').getByRole('region', { name: title, exact: true })).toHaveCount(1);
  await expect(section(page, 'Other notes').getByRole('region', { name: title, exact: true })).toHaveCount(0);
  await note(page, title).hover();
  await expect(action(note(page, title), `Unpin ${title}`)).toHaveAttribute('aria-pressed', 'true');
});

test('REQ-2.5: Unpin an existing note', async ({ page }, info) => {
  await openHome(page);
  const title = identity(info, 'Meeting agenda 2.8.2');
  await createNote(page, title, 'Keep meeting content', { pinned: true });
  await note(page, title).hover();
  await action(note(page, title), `Unpin ${title}`).click();
  await page.reload();
  await expectNote(page, title, 'Keep meeting content');
  await expect(section(page, 'Pinned notes').getByRole('region', { name: title, exact: true })).toHaveCount(0);
  await expect(section(page, 'Other notes').getByRole('region', { name: title, exact: true })).toHaveCount(1);
  await note(page, title).hover();
  await expect(action(note(page, title), `Pin ${title}`)).toHaveAttribute('aria-pressed', 'false');
});

test('REQ-2.5: Create a pinned note', async ({ page }, info) => {
  await openHome(page);
  const title = identity(info, 'Pinned at creation');
  await createNote(page, title, 'Pinned creation content', { pinned: true });
  await page.reload();
  await expectNote(page, title, 'Pinned creation content');
  await expect(section(page, 'Pinned notes').getByRole('region', { name: title, exact: true })).toHaveCount(1);
  await expect(section(page, 'Other notes').getByRole('region', { name: title, exact: true })).toHaveCount(0);
  await note(page, title).hover();
  await expect(action(note(page, title), `Unpin ${title}`)).toHaveAttribute('aria-pressed', 'true');
});

import { createHash, randomBytes } from 'node:crypto';
import type { TestInfo } from '@playwright/test';

const runId = randomBytes(8).toString('hex');

export function identity(info: TestInfo, example: string): string {
  const caseId = createHash('sha256').update(info.title).digest('hex').slice(0, 10);
  // Hex-only suffixes cannot accidentally match the keyword "st".
  return `${example} [${runId}-w${info.workerIndex}-${caseId}]`;
}

import { expect, test, type Locator, type Page } from '@playwright/test';
export { test, expect };
export const action = (scope: Page | Locator, name: string) =>
  scope.getByRole('button', { name, exact: true });
export const note = (page: Page, title: string) =>
  page.getByRole('region', { name: title, exact: true });
export const section = (page: Page, name: string) =>
  page.getByRole('region', { name, exact: true });
export const editor = (page: Page) => page.getByRole('dialog', { name: 'Note editor', exact: true });
export const notice = (page: Page, name: string) => page.getByRole('status', { name, exact: true });

export async function openHome(page: Page) {
  await page.goto('/');
  await expect(action(page, 'Take a note')).toBeVisible();
}
export async function navigate(page: Page, name: string) {
  await action(page.getByRole('navigation', { name: 'Sidebar', exact: true }), name).click();
}
export async function beginNote(page: Page) {
  await action(page, 'Take a note').click();
  await expect(editor(page)).toBeVisible();
}
export async function createNote(page: Page, title: string, content: string,
  options: { pinned?: boolean } = {}) {
  await beginNote(page);
  await editor(page).getByRole('textbox', { name: 'Title', exact: true }).fill(title);
  await editor(page).getByRole('textbox', { name: 'Content', exact: true }).fill(content);
  if (options.pinned) await action(editor(page), 'Pin note').click();
  await action(editor(page), 'Close').click();
  await expect(editor(page)).toBeHidden();
  await expectNote(page, title, content);
}
export async function expectNote(page: Page, title: string, content?: string) {
  await expect(note(page, title)).toHaveCount(1);
  await expect(note(page, title)).toBeVisible();
  await expect(note(page, title).getByText(title, { exact: true })).toBeVisible();
  if (content !== undefined) await expect(note(page, title).getByText(content, { exact: true })).toBeVisible();
}
export async function archiveNote(page: Page, title: string) {
  await note(page, title).hover();
  await action(note(page, title), `Archive ${title}`).click();
  await expect(note(page, title)).toBeHidden();
  await expect(notice(page, 'Note archived')).toBeVisible();
}
